import BufferView from '../../viewer.mjs'
import { encodeString } from '../../utils/strings.mjs'

export function parse (bytes) {
  const view = new BufferView(bytes)
  const brandsStr = view.getString(8, view.byteLength - 8)
  const compBrands = typeof brandsStr === 'string' && brandsStr.length % 4 === 0 ? brandsStr.match(/.{4}/g) : []

  return {
    brand: view.getString(0, 4),
    minor: view.getUint32(4),
    compatibleBrands: compBrands
  }
}

export function validate (value) {
  const { brand, minor, compatibleBrands } = value
  if (typeof brand !== 'string' || brand.length !== 4) {
    throw new Error('`ftyp` brand is invalid')
  }

  if (typeof minor !== 'number' || minor < 0 || minor > 4294967295) {
    throw new Error('`ftyp` minor is invalid')
  }

  if (!Array.isArray(compatibleBrands) || compatibleBrands.some(brand => brand.length !== 4)) {
    throw new Error('`ftyp` compatibleBrands is invalid')
  }
}

export function encode (value) {
  const { brand, minor, compatibleBrands } = value
  const bytes = []
  const brandBytes = encodeString(brand)
  bytes.push(...brandBytes)

  const minorView = new BufferView(4)
  minorView.setUint32(0, minor)
  bytes.push(...minorView.getUint8(0, 4))

  const compatibleBrandsBytes = encodeString(compatibleBrands.join(''))
  bytes.push(...compatibleBrandsBytes)

  return bytes
}
